  typia.assert(paginated);
  // Test 10: Default pagination parameters
  const defaultPagination = await api.functional.todoApp.sessions.index(
    connection,
    {
      body: {} satisfies ITodoAppUserSession.IRequest,
    },
  );
  typia.assert(defaultPagination);
}

