  typia.assert(sortedByExpiredAsc);
  // Test 5: Sort by ip ascending
  const sortedByIpAsc = await api.functional.todoApp.sessions.index(
    connection,
    {
      body: {
        sort: "ip",
        order: "asc",
      } satisfies ITodoAppUserSession.IRequest,
